(7397554, 1163768, 51001, '<td valign="top">I think your idea was good; IMO, less background blur would have made for a more interesting photo.</td>', 'I think your idea was good; IMO, less background blur would have made for a more interesting photo.', '2015-08-15 16:16:36.000000', NULL, 1),
(7397558, 1163449, 51001, '<td valign="top">Suggestions:  turn the wheels "straight" (more or less) so it looks like the cart''s actually moving.  Tracks in the dirt (even if fake) would also have been a plus.</td>', 'Suggestions:  turn the wheels "straight" (more or less) so it looks like the cart''s actually moving.  Tracks in the dirt (even if fake) would also have been a plus.', '2015-08-15 16:25:16.000000', NULL, 1),
