(7397566, 1163798, 62249, '<td valign="top">I like the saturated blue against his fellow jacket.</td>', 'I like the saturated blue against his fellow jacket.', '2015-08-15 16:47:18.000000', NULL, 1),
(7397567, 1163539, 62249, '<td valign="top">The composition has too much going on. There''s no clear subject. Most prominent element is the front of the silver SUV.</td>', 'The composition has too much going on. There''s no clear subject. Most prominent element is the front of the silver SUV.', '2015-08-15 16:49:32.000000', NULL, 1),
(7397568, 1163695, 62249, '<td valign="top">A funny take on the challenge. Love the floral bag in the lower right part of the frame, and the hairdo of the woman facing the camera is great.</td>', 'A funny take on the challenge. Love the floral bag in the lower right part of the frame, and the hairdo of the woman facing the camera is great.', '2015-08-15 16:50:47.000000', NULL, 1),
