(7397570, 1163864, 62249, '<td valign="top">Nice. I like the repeated pattern. Wish the lead wheel were a bit sharper. Looks like focal point is really on the second wheel.</td>', 'Nice. I like the repeated pattern. Wish the lead wheel were a bit sharper. Looks like focal point is really on the second wheel.', '2015-08-15 16:51:59.000000', NULL, 1),
(7397571, 1163700, 62249, '<td valign="top">Sweet.</td>', 'Sweet.', '2015-08-15 16:52:16.000000', NULL, 1),
(7397572, 1163447, 62249, '<td valign="top">The idea for this is excellent ( the shadow of the cart more prominent than the cart itself). Wish you''d done this with an empty cart so that the wire of the cart made a cool shadow pattern.</td>', 'The idea for this is excellent ( the shadow of the cart more prominent than the cart itself). Wish you''d done this with an empty cart so that the wire of the cart made a cool shadow pattern.', '2015-08-15 16:53:25.000000', NULL, 1),
