(7397574, 1163830, 62249, '<td valign="top">This almost works. I like the idea of framing the scene with the car window and driver''s arm. Wish you were closer to the people and the shopping cart so that they were larger in the frame.</td>', 'This almost works. I like the idea of framing the scene with the car window and driver''s arm. Wish you were closer to the people and the shopping cart so that they were larger in the frame.', '2015-08-15 16:55:20.000000', NULL, 1),
(7397575, 1163821, 62249, '<td valign="top">Works well in B/W. Good tonal range.</td>', 'Works well in B/W. Good tonal range.', '2015-08-15 16:55:56.000000', NULL, 1),
(7397576, 1163794, 62249, '<td valign="top">HDR worked well on this one.</td>', 'HDR worked well on this one.', '2015-08-15 16:56:16.000000', NULL, 1),
