(7398374, 1163831, 50641, '<td valign="top">For recklessly putting all your eggs  in one basket, we are delighted to include you in the court of spleen.<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1156027" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg"/></a></td>', 'For recklessly putting all your eggs  in one basket, we are delighted to include you in the court of spleen. ', '2015-08-19 00:27:19.000000', NULL, 1),
(7398375, 1163485, 108069, '<td valign="top">That wall is quite a find. Nice framing.</td>', 'That wall is quite a find. Nice framing.', '2015-08-19 00:29:53.000000', NULL, 1),
