(7398383, 1163290, 108069, '<td valign="top">Beyond words, but I''ll embarrass myself anyway. My eyes go this way, and then that way, like a whirlpool, yet only in the top quarter of the frame. It''s like a treadmill and all the rest is ignored or forgotten. That''s probably not unlike the life of a shopping cart.<br/> <br/>And that lady and that title. Genius.<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1155933" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155933.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155933.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155933.jpg"/></a></td>', 'Beyond words, but I''ll embarrass myself anyway. My eyes go this way, and then that way, like a whirlpool, yet only in the top quarter of the frame. It''s like a treadmill and all the rest is ignored or forgotten. That''s probably not unlike the life of a shopping cart. And that lady and that title. Genius. ', '2015-08-19 00:51:11.000000', NULL, 1),
(7398385, 1163830, 108069, '<td valign="top">The divide is enormous. Processed in a timeless sense, and sadly it is timeless.<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1155943" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155943.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155943.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155943.jpg"/></a></td>', 'The divide is enormous. Processed in a timeless sense, and sadly it is timeless. ', '2015-08-19 00:52:59.000000', NULL, 1),
(7398387, 1163745, 108069, '<td valign="top">Shine is right. Beautiful contrast in this, lines and repetition, rhythm. A guilty-pleasure techno track. Nice one.<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1155942" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155942.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155942.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155942.jpg"/></a></td>', 'Shine is right. Beautiful contrast in this, lines and repetition, rhythm. A guilty-pleasure techno track. Nice one. ', '2015-08-19 00:56:30.000000', NULL, 1),
(7398388, 1163373, 68504, '<td valign="top">there is magnificence here. it requires us.<br/> <br/>pleased to invite you to spleen court <a href="//www.dpchallenge.com/image.php?IMAGE_ID=1156027" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/50641/120/Copyrighted_Image_Reuse_Prohibited_1156027.jpg"/></a></td>', 'there is magnificence here. it requires us. pleased to invite you to spleen court ', '2015-08-19 00:58:33.000000', NULL, 1),
(7398389, 1163776, 108069, '<td valign="top">If I think of shopping carts I think of shadows, and this is a unique entry in that sense. Nicely done. A representation of all they are without even showing them.<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1155941" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155941.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155941.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/105000-109999/108069/120/Copyrighted_Image_Reuse_Prohibited_1155941.jpg"/></a></td>', 'If I think of shopping carts I think of shadows, and this is a unique entry in that sense. Nicely done. A representation of all they are without even showing them. ', '2015-08-19 00:58:49.000000', NULL, 1);
