(7398408, 1163290, 3724, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=753886" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg"/></a> <br/> <br/>good subject composition - 9</td>', '  good subject composition - 9', '2015-08-19 01:19:29.000000', NULL, 0),
(7398417, 1163793, 3724, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=753886" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/0-4999/3724/120/Copyrighted_Image_Reuse_Prohibited_753886.jpg"/></a> <br/> <br/>refreshing cart pov - 9</td>', '  refreshing cart pov - 9', '2015-08-19 01:28:56.000000', NULL, 0),
